BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog,public;
SELECT jsonb_build_object('version',version(),'captured_at',clock_timestamp(),
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'hash',md5(pg_get_functiondef(p.oid)),'body_hash',md5(replace(p.prosrc,chr(13)||chr(10),chr(10))),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl,'security_definer',p.prosecdef,
'dependencies',(SELECT coalesce(jsonb_agg(pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid) ORDER BY pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid)),'[]') FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid))
ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','app_private') AND (p.proname ILIKE '%point%' OR p.proname ILIKE '%punto%')),
'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'table',c.relname,'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('points_cycles','points_transactions','points_rules','points_rule_services','points_legacy_migrations','citas','citas_grupos','citas_detalles','clientes','personas','usuarios','sucursales','servicios','payments','payment_intents','subscriptions','subscription_consumptions','subscription_payments','membership_purchase_orders','payment_events','payment_providers','tipos_puntos','estados_cita') AND NOT t.tgisinternal),
'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.table_name,'name',c.column_name,'type',c.udt_name,'nullable',c.is_nullable,'default',c.column_default) ORDER BY c.table_name,c.ordinal_position) FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name IN('points_cycles','points_transactions','points_rules','points_rule_services','points_legacy_migrations','citas','citas_grupos','citas_detalles','clientes','personas','usuarios','sucursales','servicios','payments','payment_intents','subscriptions','subscription_consumptions','subscription_payments','membership_purchase_orders','payment_events','payment_providers','tipos_puntos','estados_cita')),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('points_cycles','points_transactions','points_rules','points_rule_services','points_legacy_migrations','citas','citas_grupos','citas_detalles','clientes','personas','usuarios','sucursales','servicios','payments','payment_intents','subscriptions','subscription_consumptions','subscription_payments','membership_purchase_orders','payment_events','payment_providers','tipos_puntos','estados_cita')),
'indexes',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname) FROM pg_indexes WHERE schemaname='public' AND tablename IN('points_cycles','points_transactions','points_rules','points_rule_services','points_legacy_migrations','citas','citas_grupos','citas_detalles','clientes','personas','usuarios','sucursales','servicios','payments','payment_intents','subscriptions','subscription_consumptions','subscription_payments','membership_purchase_orders','payment_events','payment_providers','tipos_puntos','estados_cita')),
'views',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_viewdef(c.oid,true),'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'options',c.reloptions) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v' AND c.relname ILIKE '%point%'),
'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations WHERE name ILIKE '%point%' OR name ILIKE '%punto%' OR name ILIKE '%seguridad%'),
'security_backup',(SELECT jsonb_agg(to_jsonb(b) ORDER BY signature) FROM app_private.security02_routine_backup b WHERE signature ILIKE '%point%' OR signature ILIKE '%punto%')
) snapshot; COMMIT;
